class Solution:
    def maxDepth(self, root):
        depths = []
        def dfs(node, d):
            if not node:
                return
            if not node.left and not node.right:
                depths.append(d)
            dfs(node.left, d + 1)
            dfs(node.right, d + 1)
        dfs(root, 1)
        return max(depths) if depths else 0

